// The office in three languages: English (the source), Albanian and Italian. `t()` looks a line up by its English
// text; what is not in the table stays English. A live brain is told the office language and answers in it (or in
// whatever language you write to it); the built-in brain speaks English only. The office's own words live here:
// the title, the clock-in desk, the HUD, the Phone, the market, the product instructions, the daily targets,
// Settings, the break room, Mr. Krull, the review, the sheets, the disasters, the three colleagues, and the few
// stock caller lines a live call still uses. Product names and their one-line jokes stay English on purpose.
// Variables: `{n}` in a key is filled from `vars`. A native speaker should read the Albanian once (Luca).
import { settings } from './game/state';

export type Lang = 'en' | 'sq' | 'it';
export function lang(): Lang { return (settings.lang === 'sq' || settings.lang === 'it') ? settings.lang : 'en'; }

export function t(s: string, vars?: Record<string, string | number>): string {
  const l = lang();
  let out = l === 'en' ? s : (DICT[l][s] ?? s);
  if (vars) for (const [k, v] of Object.entries(vars)) out = out.split(`{${k}}`).join(String(v));
  return out;
}

